import React, { useEffect, useMemo, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, useReducedMotion, animate } from "motion/react";
import { Home, Dumbbell, HeartPulse, BarChart3, Flame, Trophy, Sparkles, LogOut, ArrowRight, Zap, RefreshCw, Check, Moon, MessageSquare } from "lucide-react";

type Row = Record<string, unknown>;
const FONT = "'Barlow Condensed','Oswald','Arial Narrow',Impact,sans-serif";
const CARD = "rounded-3xl border border-white/[0.07] bg-[#13150e] shadow-[0_1px_0_rgba(255,255,255,0.05)_inset,0_24px_48px_-24px_rgba(0,0,0,0.9)]";
const NAV = [
  { to: "/", label: "Home", I: Home },
  { to: "/log", label: "Log", I: Dumbbell },
  { to: "/checkin", label: "Check-in", I: HeartPulse },
  { to: "/activity", label: "Activity", I: BarChart3 },
];

const ds = (v: unknown): string => String(v ?? "").slice(0, 10);
const num = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
const addDays = (s: string, n: number): string => {
  const d = new Date(s + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};
const dow = (s: string): number => (new Date(s + "T00:00:00Z").getUTCDay() + 6) % 7;
const DAYS = ["M", "T", "W", "T", "F", "S", "S"];

type Ex = { n?: string; s?: number; r?: number; w?: number; km?: number; min?: number };
function parseEx(v: unknown): Ex[] {
  try {
    const j = JSON.parse(String(v ?? "[]"));
    return Array.isArray(j) ? (j as Ex[]) : [];
  } catch (e) {
    return [];
  }
}
function calcStreak(days: Set<string>, today: string): number {
  let cur = days.has(today) ? today : addDays(today, -1);
  let n = 0;
  while (days.has(cur)) {
    n++;
    cur = addDays(cur, -1);
  }
  return n;
}

function Counter({ value, decimals = 0 }: { value: number; decimals?: number }) {
  const reduce = useReducedMotion();
  const [v, setV] = useState(reduce ? value : 0);
  useEffect(() => {
    if (reduce) {
      setV(value);
      return;
    }
    const c = animate(0, value, { duration: 1.2, ease: "easeOut", onUpdate: (x) => setV(x) });
    return () => c.stop();
  }, [value, reduce]);
  return <>{decimals ? v.toFixed(decimals) : Math.round(v).toLocaleString()}</>;
}

function Shell({ app, active, children }: { app?: AppHandle; active: string; children: React.ReactNode }) {
  return (
    <div className="min-h-screen bg-[#0a0b08] text-white antialiased">

      <aside className="fixed inset-y-0 left-0 z-30 hidden w-64 flex-col border-r border-white/[0.06] bg-[#0c0d09] p-5 lg:flex">
        <div className="mb-8 flex items-center gap-2">
          <div className="grid h-9 w-9 place-items-center rounded-xl bg-primary text-black"><Zap size={20} strokeWidth={2.8} /></div>
          <span className="text-3xl font-extrabold uppercase tracking-tight" style={{ fontFamily: FONT }}>Stride</span>
        </div>
        <nav className="space-y-1">
          {NAV.map((n) => (
            <button key={n.to} onClick={() => app?.navigate(n.to)} className="relative flex w-full items-center gap-3 rounded-2xl px-4 py-3 text-left text-sm font-semibold">
              {active === n.to && <motion.span layoutId="side-pill" className="absolute inset-0 rounded-2xl bg-primary/15 ring-1 ring-primary/40" />}
              <n.I size={18} className={active === n.to ? "relative text-primary" : "relative text-white/50"} />
              <span className={active === n.to ? "relative text-white" : "relative text-white/60"}>{n.label}</span>
            </button>
          ))}
        </nav>
        <div className="mt-auto flex items-center gap-3 rounded-2xl bg-white/[0.04] p-3">
          <div className="grid h-10 w-10 place-items-center rounded-full bg-primary/20 font-bold text-primary">{(app?.user.name || "A").slice(0, 1)}</div>
          <div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold">{app?.user.name}</div><div className="text-xs text-white/40">Athlete</div></div>
          <button aria-label="Sign out" onClick={() => app?.auth.signOut()} className="text-white/40 hover:text-white"><LogOut size={18} /></button>
        </div>
      </aside>
      <main className="lg:pl-64"><div className="mx-auto max-w-6xl px-4 pb-32 pt-6 lg:px-10 lg:pb-12">{children}</div></main>
      <nav className="fixed inset-x-0 bottom-0 z-40 border-t border-white/[0.08] bg-[#0c0d09]/90 px-2 pb-[max(env(safe-area-inset-bottom),8px)] pt-2 backdrop-blur-xl lg:hidden">
        <div className="mx-auto grid max-w-md grid-cols-4">
          {NAV.map((n) => {
            const on = active === n.to;
            const center = n.to === "/log";
            return (
              <motion.button key={n.to} whileTap={{ scale: 0.9 }} onClick={() => app?.navigate(n.to)} className="flex flex-col items-center gap-1 py-1">
                <span className={center ? "-mt-6 grid h-12 w-12 place-items-center rounded-2xl bg-primary text-black shadow-[0_10px_30px_-6px_rgba(198,244,50,0.6)]" : "grid h-8 place-items-center"}>
                  <n.I size={center ? 22 : 20} strokeWidth={center ? 2.8 : 2} className={center ? "" : on ? "text-primary" : "text-white/45"} />
                </span>
                <span className={on ? "text-[10px] font-semibold text-primary" : "text-[10px] text-white/45"}>{n.label}</span>
              </motion.button>
            );
          })}
        </div>
      </nav>
    </div>
  );
}

function Ring({ pct, size = 230, stroke = 16, children }: { pct: number; size?: number; stroke?: number; children: React.ReactNode }) {
  const reduce = useReducedMotion();
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  return (
    <div className="relative" style={{ width: size, height: size }}>
      <motion.div className="absolute inset-4 rounded-full bg-primary/10 blur-2xl" animate={reduce ? undefined : { opacity: [0.4, 1, 0.4] }} transition={{ duration: 3.2, repeat: Infinity }} />
      <svg width={size} height={size} className="-rotate-90">
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="rgba(255,255,255,0.07)" strokeWidth={stroke} />
        <motion.circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="hsl(var(--primary))" strokeWidth={stroke} strokeLinecap="round" strokeDasharray={c} initial={{ strokeDashoffset: c }} animate={{ strokeDashoffset: c * (1 - Math.min(1, Math.max(0.02, pct))) }} transition={{ duration: reduce ? 0 : 1.4, ease: [0.22, 1, 0.36, 1] }} style={{ filter: "drop-shadow(0 0 10px hsl(var(--primary) / 0.7))" }} />
      </svg>
      <div className="absolute inset-0 grid place-items-center">{children}</div>
    </div>
  );
}

export default function AthleteHome({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [today] = useState(() => new Date().toISOString().slice(0, 10));
  const [hour] = useState(() => new Date().getHours());
  const [metric, setMetric] = useState<"minutes" | "volume" | "distance">("minutes");
  const [tip, setTip] = useState("");
  const [tipBusy, setTipBusy] = useState(false);
  const [tipAi, setTipAi] = useState(false);
  const [picked, setPicked] = useState<number | null>(null);

  const me = app?.me("athlete");
  const loading = app ? app.loading("workout") : false;
  const all = app ? app.rows("workout") : [];
  const plans = app ? app.rows("plan_day") : [];
  const checkins = app ? app.rows("checkin") : [];
  const feedback = app ? app.rows("feedback") : [];
  const digests = app ? app.rows("digest") : [];
  const athletes = app ? app.rows("athlete") : [];
  const coaches = app ? app.rows("coach") : [];
  const mine = athletes.find((a) => String(a.id) === me) || athletes[0];
  const coach = coaches.find((c) => mine && String(c.id) === String(mine.coach_id));

  const workouts = useMemo(() => all.filter((w) => !me || String(w.athlete_id) === me), [all, me]);
  const days = useMemo(() => new Set(workouts.map((w) => ds(w.day))), [workouts]);
  const streak = calcStreak(days, today);
  const best = useMemo(() => {
    const sorted = Array.from(days).sort();
    let b = 0;
    let run = 0;
    let prev = "";
    for (const d of sorted) {
      run = prev && addDays(prev, 1) === d ? run + 1 : 1;
      if (run > b) b = run;
      prev = d;
    }
    return b;
  }, [days]);
  const weekStart = addDays(today, -dow(today));
  const week = useMemo(() => {
    return DAYS.map((_, i) => {
      const d = addDays(weekStart, i);
      const ws = workouts.filter((w) => ds(w.day) === d);
      return { d, minutes: ws.reduce((s, w) => s + num(w.duration_min), 0), volume: ws.reduce((s, w) => s + num(w.volume), 0), distance: ws.reduce((s, w) => s + num(w.distance_km), 0), n: ws.length };
    });
  }, [workouts, weekStart]);
  const sessions = week.reduce((s, d) => s + d.n, 0);
  const target = num(mine?.weekly_target) || 5;
  const wkWorkouts = workouts.filter((w) => ds(w.day) >= weekStart && ds(w.day) <= today);
  const avgEffort = wkWorkouts.length ? wkWorkouts.reduce((s, w) => s + num(w.effort), 0) / wkWorkouts.length : 0;
  const totMin = week.reduce((s, d) => s + d.minutes, 0);
  const totVol = week.reduce((s, d) => s + d.volume, 0);

  const todayPlan = plans.find((p) => ds(p.day) === today && (!me || String(p.athlete_id) === me));
  const doneToday = workouts.some((w) => ds(w.day) === today);
  const checkedIn = checkins.some((c) => ds(c.day) === today && (!me || String(c.athlete_id) === me));
  const lastCheckin = [...checkins].sort((a, b) => ds(b.day).localeCompare(ds(a.day)))[0];

  const prs = useMemo(() => {
    const lifts = new Map<string, { w: number; r: number; day: string }>();
    let longest = { km: 0, day: "" };
    let pace = { p: 99, day: "", km: 0 };
    for (const w of workouts) {
      for (const e of parseEx(w.exercises)) {
        const wt = num(e.w);
        if (e.n && wt > 0) {
          const cur = lifts.get(e.n);
          if (!cur || wt > cur.w || (wt === cur.w && ds(w.day) > cur.day)) lifts.set(e.n, { w: wt, r: num(e.r), day: ds(w.day) });
        }
      }
      if (String(w.kind) === "run") {
        const km = num(w.distance_km);
        if (km > longest.km) longest = { km, day: ds(w.day) };
        if (km >= 3) {
          const p = num(w.duration_min) / km;
          if (p < pace.p) pace = { p, day: ds(w.day), km };
        }
      }
    }
    const fresh = addDays(today, -7);
    const out: { name: string; value: string; day: string; isNew: boolean; run: boolean }[] = [];
    Array.from(lifts.entries()).sort((a, b) => b[1].w - a[1].w).slice(0, 4).forEach(([n, v]) => out.push({ name: n, value: v.w + " kg" + (v.r ? " × " + v.r : ""), day: v.day, isNew: v.day > fresh, run: false }));
    if (longest.km) out.push({ name: "Longest run", value: longest.km + " km", day: longest.day, isNew: longest.day > fresh, run: true });
    if (pace.p < 99) {
      const m = Math.floor(pace.p);
      const s = Math.round((pace.p - m) * 60);
      out.push({ name: "Best pace", value: m + ":" + String(s).padStart(2, "0") + " /km", day: pace.day, isNew: pace.day > fresh, run: true });
    }
    return out;
  }, [workouts, today]);

  const recent = useMemo(() => workouts.filter((w) => ds(w.day) >= addDays(today, -6)).sort((a, b) => ds(b.day).localeCompare(ds(a.day))), [workouts, today]);
  const fbList = useMemo(() => [...feedback].sort((a, b) => String(b.created_at ?? "").localeCompare(String(a.created_at ?? ""))).slice(0, 2), [feedback]);
  const lastDigest = [...digests].sort((a, b) => ds(b.week_start).localeCompare(ds(a.week_start)))[0];

  function fallbackTip(): string {
    if (!recent.length) return "No sessions logged this week yet — even a 20-minute easy session keeps the streak and the habit alive.";
    const hard = recent.filter((w) => num(w.effort) >= 8).length;
    const sore = lastCheckin ? num(lastCheckin.soreness) : 0;
    if (sore >= 4) return "Soreness is high on your last check-in — swap the next hard session for 30 minutes of mobility and sleep an extra hour.";
    if (hard >= 3) return "You've logged " + hard + " sessions at effort 8+ this week. Make the next one an easy 5 — the gains land during recovery.";
    const top = recent[0];
    return "Nice work on " + String(top.title) + ". Keep your next session at effort " + Math.max(5, Math.min(8, num(top.effort))) + " and aim to match, not beat, last week's numbers.";
  }

  async function getTip() {
    if (!app) return;
    setTipBusy(true);
    const lines = recent.map((w) => ds(w.day) + ": " + String(w.title) + " (" + String(w.kind) + "), effort " + num(w.effort) + "/10, " + num(w.duration_min) + " min" + (num(w.volume) ? ", " + num(w.volume) + " kg volume" : "") + (num(w.distance_km) ? ", " + num(w.distance_km) + " km" : "") + (w.notes ? ", note: " + String(w.notes) : ""));
    const ck = checkins.filter((c) => ds(c.day) >= addDays(today, -6)).map((c) => ds(c.day) + ": sleep " + num(c.sleep_hours) + " h, mood " + num(c.mood) + "/5, soreness " + num(c.soreness) + "/5");
    try {
      const a = await app.ai.ask("Athlete logs from the last 7 days:\n" + lines.join("\n") + "\nCheck-ins:\n" + ck.join("\n") + "\nGoal: " + String(mine?.goal ?? "get fitter") + "\nGive ONE specific coaching tip for the next session.", { system: "You are a sharp, warm strength and endurance coach. Reply with exactly one tip in at most two short sentences. Cite a concrete number or exercise from the logs. No preamble, no lists, no emoji.", maxTokens: 120 });
      const t = a.trim();
      if (t) {
        setTip(t);
        setTipAi(true);
      } else throw new Error("empty");
    } catch (e) {
      setTip(fallbackTip());
      setTipAi(false);
    }
    setTipBusy(false);
  }

  const ready = !loading && workouts.length > 0;
  useEffect(() => {
    if (ready && !tip && !tipBusy) void getTip();
    // eslint-disable-next-line
  }, [ready]);

  const maxV = Math.max(1, ...week.map((d) => (metric === "minutes" ? d.minutes : metric === "volume" ? d.volume : d.distance)));
  const unit = metric === "minutes" ? "min" : metric === "volume" ? "kg" : "km";
  const greet = hour < 12 ? "Good morning" : hour < 18 ? "Good afternoon" : "Good evening";
  const first = (app?.user.name || "Athlete").split(" ")[0];
  const fadeUp = (i: number) => ({ initial: reduce ? false : { opacity: 0, y: 22 }, animate: { opacity: 1, y: 0 }, transition: { delay: reduce ? 0 : 0.06 * i, type: "spring" as const, stiffness: 120, damping: 18 } });

  return (
    <Shell app={app} active="/">
      <motion.header {...fadeUp(0)} className="mb-6 flex items-center justify-between">
        <div>
          <div className="text-xs font-semibold uppercase tracking-[0.2em] text-white/40">{new Date(today + "T00:00:00Z").toLocaleDateString(undefined, { weekday: "long", month: "short", day: "numeric", timeZone: "UTC" })}</div>
          <h1 className="text-4xl font-extrabold uppercase leading-[0.95] sm:text-5xl lg:text-6xl" style={{ fontFamily: FONT }}>{greet}, <span className="text-primary">{first}</span></h1>
        </div>
        <div className="grid h-12 w-12 place-items-center overflow-hidden rounded-full bg-primary/20 text-lg font-bold text-primary ring-2 ring-primary/40 lg:hidden">
          {mine?.photo ? <img alt="" src={String(mine.photo)} className="h-full w-full object-cover" /> : first.slice(0, 1)}
        </div>
      </motion.header>

      <div className="grid gap-5 lg:grid-cols-12">
        <motion.section {...fadeUp(1)} className={CARD + " relative overflow-hidden p-6 lg:col-span-5"}>
          <div className="pointer-events-none absolute -right-16 -top-16 h-56 w-56 rounded-full bg-primary/10 blur-3xl" />
          <div className="flex items-center justify-between">
            <span className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.2em] text-white/50"><Flame size={16} className="text-primary" /> Streak</span>
            <span className="rounded-full bg-white/[0.06] px-3 py-1 text-xs text-white/60">Best {Math.max(best, streak)} days</span>
          </div>
          <div className="mt-4 flex justify-center">
            {loading ? <div className="h-[230px] w-[230px] animate-pulse rounded-full bg-white/5" /> : (
              <Ring pct={sessions / target}>
                <div className="text-center">
                  <div className="text-8xl font-extrabold leading-none text-white" style={{ fontFamily: FONT }}><Counter value={streak} /></div>
                  <div className="mt-1 text-sm font-bold uppercase tracking-[0.25em] text-primary">day streak</div>
                  <div className="mt-1 text-xs text-white/45">{sessions}/{target} sessions this week</div>
                </div>
              </Ring>
            )}
          </div>
          <div className="mt-5 grid grid-cols-7 gap-1.5">
            {week.map((d, i) => {
              const isToday = d.d === today;
              return (
                <motion.div key={d.d} initial={reduce ? false : { scale: 0.5, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ delay: 0.5 + i * 0.05, type: "spring", stiffness: 260, damping: 16 }} className="flex flex-col items-center gap-1.5">
                  <span className={d.n ? "grid h-9 w-9 place-items-center rounded-full bg-primary text-black" : isToday ? "grid h-9 w-9 place-items-center rounded-full border-2 border-dashed border-primary/70" : "grid h-9 w-9 place-items-center rounded-full bg-white/[0.06]"}>{d.n ? <Check size={16} strokeWidth={3.5} /> : null}</span>
                  <span className={isToday ? "text-[11px] font-bold text-primary" : "text-[11px] text-white/40"}>{DAYS[i]}</span>
                </motion.div>
              );
            })}
          </div>
        </motion.section>

        <motion.section {...fadeUp(2)} className={CARD + " relative min-h-[320px] overflow-hidden lg:col-span-7"}>
          {todayPlan?.image ? <img alt="" src={String(todayPlan.image)} className="absolute inset-0 h-full w-full object-cover opacity-55" /> : null}
          <div className="absolute inset-0 bg-gradient-to-t from-[#0a0b08] via-[#0a0b08]/70 to-transparent" />
          <div className="relative flex h-full min-h-[320px] flex-col justify-end p-6">
            <span className="mb-3 w-fit rounded-full bg-primary px-3 py-1 text-[11px] font-extrabold uppercase tracking-[0.2em] text-black">{doneToday ? "Done today" : "Today's workout"}</span>
            {todayPlan ? (
              <>
                <h2 className="text-5xl font-extrabold uppercase leading-[0.95] lg:text-6xl" style={{ fontFamily: FONT }}>{String(todayPlan.title)}</h2>
                <p className="mt-2 max-w-lg text-sm text-white/70">{String(todayPlan.details ?? "")}</p>
                <div className="mt-5 flex flex-wrap items-center gap-3">
                  <motion.button whileTap={{ scale: 0.95 }} whileHover={{ scale: 1.03 }} onClick={() => app?.navigate("/log")} className="flex h-12 items-center gap-2 rounded-2xl bg-primary px-6 text-base font-extrabold uppercase tracking-wide text-black shadow-[0_12px_36px_-8px_rgba(198,244,50,0.6)]" style={{ fontFamily: FONT }}>
                    {doneToday ? "Log another" : "Start & log"} <ArrowRight size={18} strokeWidth={3} />
                  </motion.button>
                  <span className="text-sm text-white/60">{num(todayPlan.duration_min)} min · {String(todayPlan.kind)}</span>
                </div>
              </>
            ) : (
              <>
                <h2 className="text-5xl font-extrabold uppercase leading-[0.95]" style={{ fontFamily: FONT }}>Open day</h2>
                <p className="mt-2 text-sm text-white/65">{coach ? String(coach.name) + " hasn't planned today — train freely or recover." : "No plan for today — train freely or recover."}</p>
                <motion.button whileTap={{ scale: 0.95 }} onClick={() => app?.navigate("/log")} className="mt-5 flex h-12 w-fit items-center gap-2 rounded-2xl bg-primary px-6 font-extrabold uppercase text-black" style={{ fontFamily: FONT }}>Log a session <ArrowRight size={18} strokeWidth={3} /></motion.button>
              </>
            )}
          </div>
        </motion.section>

        <motion.section {...fadeUp(3)} className="grid grid-cols-2 gap-3 lg:col-span-12 lg:grid-cols-4">
          {[{ l: "Sessions", v: sessions, d: 0, u: "" }, { l: "Minutes", v: totMin, d: 0, u: "min" }, { l: "Volume", v: totVol, d: 0, u: "kg" }, { l: "Avg effort", v: avgEffort, d: 1, u: "/10" }].map((s, i) => (
            <motion.div key={s.l} whileHover={{ y: -3 }} whileTap={{ scale: 0.97 }} className={CARD + " p-4"}>
              <div className="text-[11px] font-semibold uppercase tracking-[0.18em] text-white/45">{s.l} · this week</div>
              <div className="mt-1 flex items-baseline gap-1"><span className="text-4xl font-extrabold leading-none sm:text-5xl" style={{ fontFamily: FONT }}><Counter value={s.v} decimals={s.d} /></span><span className="text-sm text-white/45">{s.u}</span></div>
            </motion.div>
          ))}
        </motion.section>

        <motion.section {...fadeUp(4)} className={CARD + " p-6 lg:col-span-7"}>
          <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
            <h3 className="text-2xl font-extrabold uppercase" style={{ fontFamily: FONT }}>Weekly volume</h3>
            <div className="flex rounded-full bg-white/[0.06] p-1">
              {([["minutes", "Minutes"], ["volume", "Kg"], ["distance", "Km"]] as const).map(([k, l]) => (
                <button key={k} onClick={() => setMetric(k)} className="relative rounded-full px-3 py-1 text-xs font-semibold">
                  {metric === k && <motion.span layoutId="metric-pill" className="absolute inset-0 rounded-full bg-primary" />}
                  <span className={metric === k ? "relative text-black" : "relative text-white/60"}>{l}</span>
                </button>
              ))}
            </div>
          </div>
          <div className="flex h-56 items-end gap-2 sm:gap-4">
            {week.map((d, i) => {
              const v = metric === "minutes" ? d.minutes : metric === "volume" ? d.volume : d.distance;
              const h = Math.max(v ? 6 : 2, (v / maxV) * 100);
              const sel = picked === i;
              return (
                <button key={d.d} onClick={() => setPicked(sel ? null : i)} className="flex h-full flex-1 flex-col items-center justify-end gap-2">
                  <span className={"text-[11px] font-semibold " + (sel || d.d === today ? "text-primary" : "text-white/45")}>{v ? Math.round(v * 10) / 10 : ""}</span>
                  <motion.div initial={reduce ? false : { height: 0 }} animate={{ height: h + "%" }} transition={{ delay: reduce ? 0 : 0.1 + i * 0.06, type: "spring", stiffness: 110, damping: 16 }} className={"w-full rounded-t-xl " + (d.d === today || sel ? "bg-primary shadow-[0_0_24px_-2px_hsl(var(--primary)/0.6)]" : v ? "bg-primary/45" : "bg-white/[0.07]")} />
