export default function StrideLogin({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const auth = app?.auth;
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const signup = auth?.mode === "signup";
  const providers = auth?.providers ?? [];

  async function go() {
    if (!auth) return;
    setErr("");
    setBusy(true);
    try {
      if (signup) await auth.signUp({ email, password, name });
      else await auth.signIn(email, password);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Something went wrong");
    }
    setBusy(false);
  }

  async function provider(p: string) {
    if (!auth) return;
    setErr("");
    try {
      await auth.startProvider(p);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't start that sign-in");
    }
  }

  const R = 46;
  const C = 2 * Math.PI * R;

  return (
    <div className="relative flex min-h-screen w-full flex-col items-center overflow-hidden bg-[#070805] px-5 pb-10 pt-8 text-white">
      <div className="pointer-events-none absolute left-1/2 top-[18%] h-[520px] w-[520px] -translate-x-1/2 -translate-y-1/2 rounded-full bg-primary/10 blur-3xl" />

      <div className="relative z-10 flex w-full max-w-md items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="grid h-8 w-8 place-items-center rounded-lg bg-primary text-black"><Zap size={18} strokeWidth={2.8} /></div>
          <span className="text-2xl font-extrabold uppercase tracking-tight" style={{ fontFamily: FONT }}>Stride</span>
        </div>
      </div>

      <div className="relative mt-6 flex w-full flex-col items-center sm:mt-8">
        <svg className="pointer-events-none absolute left-1/2 top-1/2 h-[120vw] max-h-[560px] w-[120vw] max-w-[560px] -translate-x-1/2 -translate-y-1/2" viewBox="0 0 100 100" aria-hidden="true">
          <circle cx="50" cy="50" r={R} fill="none" stroke="rgba(255,255,255,0.05)" strokeWidth="0.8" />
          <motion.circle
            cx="50" cy="50" r={R} fill="none" stroke="hsl(var(--primary))" strokeWidth="1.6" strokeLinecap="round"
            strokeDasharray={C} transform="rotate(-90 50 50)"
            initial={{ strokeDashoffset: reduce ? C * 0.25 : C }}
            animate={{ strokeDashoffset: C * 0.25 }}
            transition={{ duration: reduce ? 0 : 1.8, ease: [0.22, 1, 0.36, 1] }}
            style={{ filter: "drop-shadow(0 0 3px hsl(var(--primary) / 0.8))" }}
          />
          <motion.g
            animate={reduce ? undefined : { rotate: 360 }}
            transition={{ duration: 9, repeat: Infinity, ease: "linear" }}
            style={{ transformOrigin: "50px 50px" }}
          >
            <circle cx="50" cy="4" r="1.7" fill="hsl(var(--primary))" style={{ filter: "drop-shadow(0 0 2px hsl(var(--primary)))" }} />
          </motion.g>
        </svg>

        <h1 aria-label="Move" className="relative flex select-none items-end justify-center font-extrabold uppercase leading-[0.82] text-primary" style={{ fontFamily: FONT, fontSize: "clamp(6rem, 29vw, 13rem)", textShadow: "0 0 60px hsl(var(--primary) / 0.35)" }}>
          {LETTERS.map((l, i) => (
            <motion.span
              key={i}
              aria-hidden="true"
              initial={reduce ? false : { y: "60%", opacity: 0, skewX: -12 }}
              animate={{ y: 0, opacity: 1, skewX: 0 }}
              transition={{ delay: reduce ? 0 : 0.15 + i * 0.09, type: "spring", stiffness: 160, damping: 16 }}
              className="inline-block"
            >
              {l}
            </motion.span>
          ))}
        </h1>
        <motion.p initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: reduce ? 0 : 0.8 }} className="relative mt-2 text-center text-sm text-white/55">
          {signup ? "Create your athlete account and start the streak." : "Your plan. Your streak. Your coach."}
        </motion.p>
      </div>

      <motion.div
        initial={reduce ? false : { opacity: 0, y: 24 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: reduce ? 0 : 0.7, type: "spring", stiffness: 110, damping: 18 }}
        className="relative z-10 mt-7 w-full max-w-sm rounded-3xl border border-white/[0.08] bg-[#0e100a]/80 p-5 backdrop-blur-xl"
      >
        <div className="space-y-3">
          {signup ? (
            <div>
              <label htmlFor="stride-name" className="mb-1 block text-[11px] font-semibold uppercase tracking-widest text-white/50">Name</label>
              <input id="stride-name" aria-label="Name" autoComplete="name" value={name} onChange={(e) => setName(e.target.value)} className={IN} />
            </div>
          ) : null}
          <div>
            <label htmlFor="stride-email" className="mb-1 block text-[11px] font-semibold uppercase tracking-widest text-white/50">Email</label>
            <input id="stride-email" aria-label="Email" type="email" autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} className={IN} />
          </div>
          <div>
            <label htmlFor="stride-password" className="mb-1 block text-[11px] font-semibold uppercase tracking-widest text-white/50">Password</label>
            <input id="stride-password" aria-label="Password" type="password" autoComplete={signup ? "new-password" : "current-password"} value={password} onChange={(e) => setPassword(e.target.value)} className={IN} />
          </div>
        </div>
        {err ? <p role="alert" className="mt-3 text-sm text-red-400">{err}</p> : null}
        <motion.button whileTap={{ scale: 0.97 }} onClick={() => void go()} disabled={busy} className="mt-4 flex w-full items-center justify-center gap-2 rounded-xl bg-primary py-3.5 text-xl font-extrabold uppercase tracking-wide text-black shadow-[0_12px_40px_-8px_rgba(198,244,50,0.55)] disabled:opacity-60" style={{ fontFamily: FONT }}>
          {signup ? "Create account" : "Sign in"} <ArrowRight size={20} strokeWidth={3} />
        </motion.button>

        {providers.length > 0 ? (
          <>
            <div className="my-4 flex items-center gap-3 text-[11px] font-semibold uppercase tracking-[0.25em] text-white/35">
              <span className="h-px flex-1 bg-white/10" />or<span className="h-px flex-1 bg-white/10" />
            </div>
            <div className="space-y-2">
              {providers.map((p) => (
                <motion.button key={p.name} whileTap={{ scale: 0.97 }} onClick={() => void provider(p.name)} className="flex h-12 w-full items-center justify-center gap-3 rounded-xl border border-white/15 bg-white text-sm font-semibold text-neutral-900">
                  {p.name === "google" ? <GoogleMark /> : null}
                  Continue with {p.label}
                </motion.button>
              ))}
            </div>
          </>
        ) : null}

        {auth?.canSignUp ? (
          <button onClick={() => auth.setMode(signup ? "login" : "signup")} className="mt-4 w-full text-center text-sm text-white/55 hover:text-white">
            {signup ? "Have an account? Log in" : "New here? Create an account"}
          </button>
        ) : null}
      </motion.div>
    </div>
  );
}

import React, { useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
