export default function CheckIn({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [today] = useState(() => new Date().toISOString().slice(0, 10));
  const me = app?.me("athlete");
  const athletes = app ? app.rows("athlete") : [];
  const mine = athletes.find((a) => String(a.id) === me) || athletes[0];
  const rows = app ? app.rows("checkin") : [];
  const existing = rows.find((c) => ds(c.day) === today);
  const [sleep, setSleep] = useState(7.5);
  const [mood, setMood] = useState(4);
  const [sore, setSore] = useState(2);
  const [note, setNote] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [saved, setSaved] = useState(false);
  const [justNow, setJustNow] = useState<Row | null>(null);

  const shown = existing || justNow;
  const hist = Array.from({ length: 7 }, (_, i) => {
    const d = addDays(today, i - 6);
    const r = rows.find((c) => ds(c.day) === d) || (d === today && justNow ? justNow : undefined);
    return { d, r };
  });

  async function save() {
    if (!app) return;
    setBusy(true);
    setErr("");
    try {
      const vals = { athlete_id: me, coach_id: mine?.coach_id ?? null, athlete_name: app.user.name, day: today, sleep_hours: sleep, mood, soreness: sore, note };
      await app.create("checkin", vals);
      setJustNow(vals);
      setSaved(true);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't save your check-in.");
    }
    setBusy(false);
  }

  const lbl = "mb-3 text-xs font-semibold uppercase tracking-[0.2em] text-white/45";
  return (
    <Shell app={app} active="/checkin">
      <motion.div initial={reduce ? false : { opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
        <div className="text-xs font-semibold uppercase tracking-[0.2em] text-white/40">20 seconds · your coach sees it</div>
        <h1 className="text-5xl font-extrabold uppercase leading-[0.95] lg:text-6xl" style={{ fontFamily: FONT }}>Daily <span className="text-primary">check-in</span></h1>
      </motion.div>

      <div className="mt-6 grid gap-5 lg:grid-cols-5">
        <div className="lg:col-span-3">
          <AnimatePresence mode="wait">
            {shown ? (
              <motion.section key="done" initial={{ opacity: 0, scale: 0.94 }} animate={{ opacity: 1, scale: 1 }} className={CARD + " relative overflow-hidden p-8 text-center"}>
                <div className="pointer-events-none absolute left-1/2 top-0 h-48 w-48 -translate-x-1/2 rounded-full bg-primary/20 blur-3xl" />
                <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: "spring", stiffness: 240, damping: 12 }} className="relative mx-auto grid h-20 w-20 place-items-center rounded-full bg-primary text-black"><Check size={40} strokeWidth={3.5} /></motion.div>
                <h2 className="relative mt-5 text-4xl font-extrabold uppercase" style={{ fontFamily: FONT }}>{saved ? "Check-in saved" : "Already checked in today"}</h2>
                <p className="relative mt-1 text-sm text-white/55">One check-in per day — come back tomorrow.</p>
                <div className="relative mt-6 grid grid-cols-3 gap-2">
                  <div className="rounded-2xl bg-white/[0.06] p-3"><div className="text-3xl font-extrabold" style={{ fontFamily: FONT }}>{num(shown.sleep_hours)}h</div><div className="text-[10px] uppercase tracking-widest text-white/45">sleep</div></div>
                  <div className="rounded-2xl bg-white/[0.06] p-3"><div className="text-3xl">{MOODS[Math.max(0, Math.min(4, num(shown.mood) - 1))]}</div><div className="text-[10px] uppercase tracking-widest text-white/45">mood</div></div>
