            ) : (
              <motion.section key="form" exit={{ opacity: 0, y: -20 }} className={CARD + " space-y-8 p-6"}>
                <div>
                  <div className={lbl}>Sleep last night</div>
                  <div className="flex items-center justify-between gap-4">
                    <motion.button whileTap={{ scale: 0.85 }} aria-label="Less sleep" onClick={() => setSleep((s) => Math.max(0, Math.round((s - 0.5) * 10) / 10))} className="grid h-14 w-14 place-items-center rounded-2xl bg-white/[0.07] text-3xl font-bold">−</motion.button>
                    <div className="text-center"><motion.span key={sleep} initial={{ y: -10, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="inline-block text-8xl font-extrabold leading-none text-primary" style={{ fontFamily: FONT }}>{sleep}</motion.span><span className="ml-1 text-xl text-white/50">h</span></div>
                    <motion.button whileTap={{ scale: 0.85 }} aria-label="More sleep" onClick={() => setSleep((s) => Math.min(14, Math.round((s + 0.5) * 10) / 10))} className="grid h-14 w-14 place-items-center rounded-2xl bg-primary text-black"><Plus /></motion.button>
                  </div>
                </div>
                <div>
                  <div className={lbl}>Mood · {MOOD_L[mood - 1]}</div>
                  <div className="grid grid-cols-5 gap-2">
                    {MOODS.map((m, i) => (
                      <motion.button key={m} whileTap={{ scale: 0.88 }} animate={{ scale: mood === i + 1 ? 1.08 : 1 }} onClick={() => setMood(i + 1)} className={"grid h-16 place-items-center rounded-2xl text-3xl " + (mood === i + 1 ? "bg-primary/20 ring-2 ring-primary" : "bg-white/[0.05]")}>{m}</motion.button>
                    ))}
                  </div>
                </div>
                <div>
                  <div className={lbl}>Soreness · {SORE_L[sore - 1]}</div>
                  <div className="grid grid-cols-5 gap-2">
                    {[1, 2, 3, 4, 5].map((n) => (
                      <motion.button key={n} whileTap={{ scale: 0.88 }} onClick={() => setSore(n)} animate={{ height: 36 + n * 10 }} className={"self-end rounded-xl text-sm font-bold " + (n <= sore ? (sore >= 4 ? "bg-orange-500 text-black" : "bg-primary text-black") : "bg-white/[0.07] text-white/40")}>{n}</motion.button>
                    ))}
                  </div>
                </div>
                <label className="block"><span className={lbl + " block"}>Anything your coach should know?</span><textarea rows={3} value={note} onChange={(e) => setNote(e.target.value)} className="w-full rounded-2xl border border-white/10 bg-white/[0.04] p-4 text-white outline-none focus:border-primary" placeholder="Optional" /></label>
                <AnimatePresence>{err ? <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="rounded-2xl border border-red-400/30 bg-red-500/10 px-4 py-3 text-sm text-red-300">{err}</motion.p> : null}</AnimatePresence>
                <motion.button whileTap={{ scale: 0.97 }} whileHover={{ scale: 1.02 }} disabled={busy} onClick={() => void save()} className="flex h-14 w-full items-center justify-center gap-2 rounded-2xl bg-primary text-xl font-extrabold uppercase text-black shadow-[0_14px_40px_-8px_rgba(198,244,50,0.55)] disabled:opacity-60" style={{ fontFamily: FONT }}>{busy ? "Saving…" : "Save check-in"}</motion.button>
