        <motion.section initial={reduce ? false : { opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }} className={CARD + " p-6 lg:col-span-2"}>
          <h3 className="mb-4 text-2xl font-extrabold uppercase" style={{ fontFamily: FONT }}>Last 7 days</h3>
          <div className={lbl.replace("mb-3", "mb-2")}>Sleep (h)</div>
          <div className="flex h-24 items-end gap-2">
            {hist.map((h, i) => (
              <div key={h.d} className="flex h-full flex-1 flex-col items-center justify-end gap-1">
                <motion.div initial={reduce ? false : { height: 0 }} animate={{ height: h.r ? Math.max(8, (num(h.r.sleep_hours) / 10) * 100) + "%" : "4%" }} transition={{ delay: i * 0.05, type: "spring", stiffness: 120, damping: 15 }} className={"w-full rounded-t-lg " + (h.r ? (num(h.r.sleep_hours) < 6 ? "bg-orange-500" : "bg-primary") : "bg-white/[0.07]")} />
                <span className="text-[10px] text-white/40">{h.d.slice(8)}</span>
              </div>
            ))}
          </div>
          <div className={lbl.replace("mb-3", "mb-2 mt-6")}>Mood</div>
          <div className="flex justify-between">{hist.map((h) => <span key={h.d} className="w-full text-center text-xl">{h.r ? MOODS[Math.max(0, Math.min(4, num(h.r.mood) - 1))] : <span className="text-white/20">·</span>}</span>)}</div>
          <div className={lbl.replace("mb-3", "mb-2 mt-6")}>Soreness</div>
          <div className="flex gap-2">{hist.map((h) => <div key={h.d} className="flex-1"><div className={"h-8 rounded-lg " + (h.r ? (num(h.r.soreness) >= 4 ? "bg-orange-500" : num(h.r.soreness) === 3 ? "bg-amber-300" : "bg-primary/70") : "bg-white/[0.07]")} style={{ opacity: h.r ? 0.4 + num(h.r.soreness) * 0.12 : 1 }} /></div>)}</div>
        </motion.section>
      </div>
    </Shell>
  );
}

import React, { useMemo, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Home, Dumbbell, HeartPulse, BarChart3, LogOut, Zap, Plus, X, Check, Flame, ArrowRight, Timer } from "lucide-react";

const FONT = "'Barlow Condensed','Oswald','Arial Narrow',Impact,sans-serif";
const CARD = "rounded-3xl border border-white/[0.07] bg-[#13150e] shadow-[0_1px_0_rgba(255,255,255,0.05)_inset,0_24px_48px_-24px_rgba(0,0,0,0.9)]";
const INPUT = "h-12 w-full rounded-2xl border border-white/10 bg-white/[0.04] px-4 text-white outline-none transition focus:border-primary";
const NAV = [
  { to: "/", label: "Home", I: Home },
  { to: "/log", label: "Log", I: Dumbbell },
  { to: "/checkin", label: "Check-in", I: HeartPulse },
  { to: "/activity", label: "Activity", I: BarChart3 },
];
const KINDS = ["strength", "run", "conditioning", "mobility", "ride", "other"] as const;
type Kind = (typeof KINDS)[number];
const PRESETS = ["Back squat", "Bench press", "Deadlift", "Overhead press", "Pull-up", "Barbell row"];

const ds = (v: unknown): string => String(v ?? "").slice(0, 10);
const num = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
const addDays = (s: string, n: number): string => {
  const d = new Date(s + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};

function Shell({ app, active, children }: { app?: AppHandle; active: string; children: React.ReactNode }) {
  return (
    <div className="min-h-screen bg-[#0a0b08] text-white antialiased">
      <aside className="fixed inset-y-0 left-0 z-30 hidden w-64 flex-col border-r border-white/[0.06] bg-[#0c0d09] p-5 lg:flex">
        <div className="mb-8 flex items-center gap-2">
          <div className="grid h-9 w-9 place-items-center rounded-xl bg-primary text-black"><Zap size={20} strokeWidth={2.8} /></div>
          <span className="text-3xl font-extrabold uppercase tracking-tight" style={{ fontFamily: FONT }}>Stride</span>
        </div>
        <nav className="space-y-1">
          {NAV.map((n) => (
            <button key={n.to} onClick={() => app?.navigate(n.to)} className="relative flex w-full items-center gap-3 rounded-2xl px-4 py-3 text-left text-sm font-semibold">
              {active === n.to && <motion.span layoutId="side-pill" className="absolute inset-0 rounded-2xl bg-primary/15 ring-1 ring-primary/40" />}
              <n.I size={18} className={active === n.to ? "relative text-primary" : "relative text-white/50"} />
              <span className={active === n.to ? "relative text-white" : "relative text-white/60"}>{n.label}</span>
            </button>
          ))}
        </nav>
        <div className="mt-auto flex items-center gap-3 rounded-2xl bg-white/[0.04] p-3">
          <div className="grid h-10 w-10 place-items-center rounded-full bg-primary/20 font-bold text-primary">{(app?.user.name || "A").slice(0, 1)}</div>
          <div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold">{app?.user.name}</div><div className="text-xs text-white/40">Athlete</div></div>
          <button aria-label="Sign out" onClick={() => app?.auth.signOut()} className="text-white/40 hover:text-white"><LogOut size={18} /></button>
        </div>
      </aside>
      <main className="lg:pl-64"><div className="mx-auto max-w-4xl px-4 pb-32 pt-6 lg:px-10 lg:pb-12">{children}</div></main>
      <nav className="fixed inset-x-0 bottom-0 z-40 border-t border-white/[0.08] bg-[#0c0d09]/90 px-2 pb-[max(env(safe-area-inset-bottom),8px)] pt-2 backdrop-blur-xl lg:hidden">
        <div className="mx-auto grid max-w-md grid-cols-4">
          {NAV.map((n) => {
            const on = active === n.to;
            const center = n.to === "/log";
            return (
              <motion.button key={n.to} whileTap={{ scale: 0.9 }} onClick={() => app?.navigate(n.to)} className="flex flex-col items-center gap-1 py-1">
                <span className={center ? "-mt-6 grid h-12 w-12 place-items-center rounded-2xl bg-primary text-black shadow-[0_10px_30px_-6px_rgba(198,244,50,0.6)]" : "grid h-8 place-items-center"}>
                  <n.I size={center ? 22 : 20} strokeWidth={center ? 2.8 : 2} className={center ? "" : on ? "text-primary" : "text-white/45"} />
                </span>
                <span className={on ? "text-[10px] font-semibold text-primary" : "text-[10px] text-white/45"}>{n.label}</span>
              </motion.button>
            );
          })}
        </div>
      </nav>
    </div>
  );
}

type Ex = { id: number; name: string; sets: string; reps: string; weight: string; km: string; min: string };

function Celebrate({ onDone, onHome, streak, volume, minutes, title }: { onDone: () => void; onHome: () => void; streak: number; volume: number; minutes: number; title: string }) {
  const reduce = useReducedMotion();
  const dots = useMemo(() => Array.from({ length: 28 }, (_, i) => ({ a: (i / 28) * Math.PI * 2, d: 120 + (i % 4) * 38, s: 6 + (i % 3) * 4, c: i % 3 })), []);
  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-50 grid place-items-center bg-[#080906]/95 px-6 backdrop-blur-md">
      <div className="relative flex w-full max-w-sm flex-col items-center text-center">
        <div className="relative grid h-44 w-44 place-items-center">
          {!reduce && dots.map((p, i) => (
            <motion.span key={i} initial={{ x: 0, y: 0, opacity: 1, scale: 0 }} animate={{ x: Math.cos(p.a) * p.d, y: Math.sin(p.a) * p.d, opacity: 0, scale: 1 }} transition={{ duration: 1.1, delay: 0.25, ease: "easeOut" }} className={"absolute rounded-full " + (p.c === 0 ? "bg-primary" : p.c === 1 ? "bg-white" : "bg-amber-300")} style={{ width: p.s, height: p.s }} />
          ))}
          <motion.span initial={{ scale: 0.4, opacity: 0.8 }} animate={{ scale: 2.4, opacity: 0 }} transition={{ duration: 1, delay: 0.2 }} className="absolute h-44 w-44 rounded-full border-4 border-primary" />
          <motion.div initial={{ scale: 0, rotate: -40 }} animate={{ scale: 1, rotate: 0 }} transition={{ type: "spring", stiffness: 220, damping: 12 }} className="grid h-36 w-36 place-items-center rounded-full bg-primary text-black shadow-[0_0_80px_hsl(var(--primary)/0.6)]">
            <motion.svg width="68" height="68" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3.4" strokeLinecap="round" strokeLinejoin="round"><motion.path d="M4 12.5l5 5L20 6.5" initial={{ pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ delay: 0.3, duration: 0.5 }} /></motion.svg>
          </motion.div>
        </div>
        <motion.h2 initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.5 }} className="mt-6 text-6xl font-extrabold uppercase leading-none" style={{ fontFamily: FONT }}>Session <span className="text-primary">done</span></motion.h2>
        <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.6 }} className="mt-2 text-white/60">{title} is in the books. Your coach has been notified.</motion.p>
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.75 }} className="mt-6 grid w-full grid-cols-3 gap-2">
          <div className="rounded-2xl bg-white/[0.06] p-3"><div className="flex items-center justify-center gap-1 text-3xl font-extrabold text-primary" style={{ fontFamily: FONT }}><Flame size={20} />{streak}</div><div className="text-[10px] uppercase tracking-widest text-white/45">day streak</div></div>
          <div className="rounded-2xl bg-white/[0.06] p-3"><div className="text-3xl font-extrabold" style={{ fontFamily: FONT }}>{minutes}</div><div className="text-[10px] uppercase tracking-widest text-white/45">minutes</div></div>
          <div className="rounded-2xl bg-white/[0.06] p-3"><div className="text-3xl font-extrabold" style={{ fontFamily: FONT }}>{volume.toLocaleString()}</div><div className="text-[10px] uppercase tracking-widest text-white/45">kg lifted</div></div>
        </motion.div>
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.9 }} className="mt-6 flex w-full gap-3">
          <motion.button whileTap={{ scale: 0.96 }} onClick={onDone} className="h-12 flex-1 rounded-2xl border border-white/15 text-sm font-semibold">Log another</motion.button>
          <motion.button whileTap={{ scale: 0.96 }} onClick={onHome} className="flex h-12 flex-1 items-center justify-center gap-2 rounded-2xl bg-primary font-extrabold uppercase text-black" style={{ fontFamily: FONT }}>Home <ArrowRight size={16} strokeWidth={3} /></motion.button>
        </motion.div>
      </div>
    </motion.div>
  );
}

export default function LogWorkout({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [today] = useState(() => new Date().toISOString().slice(0, 10));
  const me = app?.me("athlete");
  const athletes = app ? app.rows("athlete") : [];
  const mine = athletes.find((a) => String(a.id) === me) || athletes[0];
  const plans = app ? app.rows("plan_day") : [];
  const workouts = app ? app.rows("workout") : [];
  const plan = plans.find((p) => ds(p.day) === today);

  const [title, setTitle] = useState("");
  const [kind, setKind] = useState<Kind>("strength");
  const [day, setDay] = useState(today);
  const [minutes, setMinutes] = useState("45");
  const [effort, setEffort] = useState(7);
  const [notes, setNotes] = useState("");
  const [exs, setExs] = useState<Ex[]>([]);
  const [nid, setNid] = useState(1);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [done, setDone] = useState<{ streak: number; volume: number; minutes: number; title: string } | null>(null);
  const [prefilled, setPrefilled] = useState(false);

  if (plan && !prefilled && !title) {
    setPrefilled(true);
    setTitle(String(plan.title));
    const k = String(plan.kind) as Kind;
    if ((KINDS as readonly string[]).includes(k)) setKind(k);
    if (plan.duration_min) setMinutes(String(num(plan.duration_min)));
  }

  const cardio = kind === "run" || kind === "ride";
  function addEx(name: string) {
    setExs((x) => [...x, { id: nid, name, sets: "3", reps: "8", weight: "", km: "", min: "" }]);
    setNid((n) => n + 1);
  }
  function patchEx(id: number, p: Partial<Ex>) {
    setExs((x) => x.map((e) => (e.id === id ? { ...e, ...p } : e)));
  }
  const volume = exs.reduce((s, e) => s + num(e.sets) * num(e.reps) * num(e.weight), 0);
  const distance = exs.reduce((s, e) => s + num(e.km), 0);

  async function save() {
    if (!app) return;
    setErr("");
    if (!title.trim()) {
      setErr("Give the session a name.");
      return;
    }
    if (day > today) {
      setErr("A workout can't be logged with a date in the future.");
      return;
    }
    setBusy(true);
    try {
      const exercises = exs.filter((e) => e.name.trim()).map((e) => (e.km || e.min ? { n: e.name, km: num(e.km), min: num(e.min) } : { n: e.name, s: num(e.sets), r: num(e.reps), w: num(e.weight) }));
      await app.create("workout", {
        athlete_id: me,
        coach_id: mine?.coach_id ?? null,
        athlete_name: app.user.name,
        day,
        title: title.trim(),
        kind,
        effort,
        duration_min: num(minutes),
        volume,
        distance_km: distance,
        exercises: JSON.stringify(exercises),
        notes,
      });
      const set = new Set(workouts.map((w) => ds(w.day)));
      set.add(day);
      let cur = set.has(today) ? today : addDays(today, -1);
      let n = 0;
      while (set.has(cur)) {
        n++;
        cur = addDays(cur, -1);
      }
      setDone({ streak: n, volume, minutes: num(minutes), title: title.trim() });
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't save that workout.");
    }
    setBusy(false);
  }

  function reset() {
    setDone(null);
    setTitle("");
    setExs([]);
    setNotes("");
    setEffort(7);
    setPrefilled(true);
  }

  const effortColor = (n: number) => (n <= 3 ? "bg-sky-400/80" : n <= 6 ? "bg-primary" : n <= 8 ? "bg-amber-400" : "bg-orange-500");
  const effortLabel = effort <= 3 ? "Easy" : effort <= 6 ? "Moderate" : effort <= 8 ? "Hard" : "All out";

  return (
    <Shell app={app} active="/log">
      <motion.div initial={reduce ? false : { opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
        <div className="text-xs font-semibold uppercase tracking-[0.2em] text-white/40">{plan ? "Planned today · " + String(plan.title) : "Free session"}</div>
        <h1 className="text-5xl font-extrabold uppercase leading-[0.95] lg:text-6xl" style={{ fontFamily: FONT }}>Log <span className="text-primary">workout</span></h1>
      </motion.div>

      <div className="mt-6 grid gap-5 lg:grid-cols-5">
        <div className="space-y-5 lg:col-span-3">
          <motion.section initial={reduce ? false : { opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.05 }} className={CARD + " space-y-4 p-5"}>
            <label className="block"><span className="mb-1 block text-xs font-semibold uppercase tracking-widest text-white/45">Session name</span><input className={INPUT} value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g. Upper body power" /></label>
            <div className="flex flex-wrap gap-2">
              {KINDS.map((k) => (
                <button key={k} onClick={() => setKind(k)} className="relative rounded-full px-4 py-2 text-sm font-semibold capitalize">
                  {kind === k && <motion.span layoutId="kind-pill" className="absolute inset-0 rounded-full bg-primary" />}
                  <span className={kind === k ? "relative text-black" : "relative text-white/65"}>{k}</span>
                </button>
              ))}
            </div>
            <div className="grid grid-cols-2 gap-3">
              <label className="block"><span className="mb-1 block text-xs font-semibold uppercase tracking-widest text-white/45">Date</span><input type="date" max={today} className={INPUT} value={day} onChange={(e) => setDay(e.target.value)} /></label>
              <label className="block"><span className="mb-1 flex items-center gap-1 text-xs font-semibold uppercase tracking-widest text-white/45"><Timer size={12} /> Minutes</span><input type="number" inputMode="numeric" className={INPUT} value={minutes} onChange={(e) => setMinutes(e.target.value)} /></label>
            </div>
          </motion.section>

          <motion.section initial={reduce ? false : { opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }} className={CARD + " p-5"}>
            <div className="mb-3 flex items-center justify-between">
              <h3 className="text-2xl font-extrabold uppercase" style={{ fontFamily: FONT }}>Exercises</h3>
              <span className="text-xs text-white/45">{volume ? volume.toLocaleString() + " kg" : ""}{volume && distance ? " · " : ""}{distance ? distance + " km" : ""}</span>
            </div>
            <div className="space-y-3">
              <AnimatePresence initial={false}>
                {exs.map((e) => (
                  <motion.div key={e.id} layout initial={{ opacity: 0, height: 0, scale: 0.96 }} animate={{ opacity: 1, height: "auto", scale: 1 }} exit={{ opacity: 0, height: 0, scale: 0.9 }} className="overflow-hidden rounded-2xl bg-white/[0.04] p-3">
                    <div className="flex items-center gap-2">
                      <input className={INPUT + " h-10 flex-1"} value={e.name} onChange={(ev) => patchEx(e.id, { name: ev.target.value })} placeholder="Exercise" />
                      <button aria-label="Remove" onClick={() => setExs((x) => x.filter((y) => y.id !== e.id))} className="grid h-10 w-10 place-items-center rounded-xl text-white/45 hover:bg-white/10"><X size={16} /></button>
                    </div>
                    {cardio ? (
                      <div className="mt-2 grid grid-cols-2 gap-2">
                        <input type="number" inputMode="decimal" className={INPUT + " h-10"} placeholder="Distance km" value={e.km} onChange={(ev) => patchEx(e.id, { km: ev.target.value })} />
                        <input type="number" inputMode="numeric" className={INPUT + " h-10"} placeholder="Minutes" value={e.min} onChange={(ev) => patchEx(e.id, { min: ev.target.value })} />
                      </div>
                    ) : (
                      <div className="mt-2 grid grid-cols-3 gap-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40">Sets<input type="number" inputMode="numeric" className={INPUT + " mt-1 h-10"} value={e.sets} onChange={(ev) => patchEx(e.id, { sets: ev.target.value })} /></label>
                        <label className="text-[10px] uppercase tracking-widest text-white/40">Reps<input type="number" inputMode="numeric" className={INPUT + " mt-1 h-10"} value={e.reps} onChange={(ev) => patchEx(e.id, { reps: ev.target.value })} /></label>
                        <label className="text-[10px] uppercase tracking-widest text-white/40">Kg<input type="number" inputMode="decimal" className={INPUT + " mt-1 h-10"} value={e.weight} onChange={(ev) => patchEx(e.id, { weight: ev.target.value })} /></label>
                      </div>
                    )}
                  </motion.div>
                ))}
              </AnimatePresence>
