import React, { useMemo, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, useReducedMotion, animate } from "motion/react";
import { LogOut, Zap, Flame, Users, MessageSquare, AlertTriangle, ChevronRight, Send, Check, Clipboard } from "lucide-react";

type Row = Record<string, unknown>;
const FONT = "'Barlow Condensed','Oswald','Arial Narrow',Impact,sans-serif";
const CARD = "rounded-3xl border border-white/[0.07] bg-[#13150e] shadow-[0_1px_0_rgba(255,255,255,0.05)_inset,0_24px_48px_-24px_rgba(0,0,0,0.9)]";
const ds = (v: unknown): string => String(v ?? "").slice(0, 10);
const num = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
const addDays = (s: string, n: number): string => {
  const d = new Date(s + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};
const MOODS = ["😞", "😕", "😐", "🙂", "🔥"];
function calcStreak(days: Set<string>, today: string): number {
  let cur = days.has(today) ? today : addDays(today, -1);
  let n = 0;
  while (days.has(cur)) {
    n++;
    cur = addDays(cur, -1);
  }
  return n;
}
function ago(d: string, today: string): string {
  const n = Math.round((new Date(today + "T00:00:00Z").getTime() - new Date(d + "T00:00:00Z").getTime()) / 86400000);
  return n <= 0 ? "today" : n === 1 ? "yesterday" : n + "d ago";
}

function MiniRing({ pct, children }: { pct: number; children: React.ReactNode }) {
  const reduce = useReducedMotion();
  const size = 64;
  const r = 28;
  const c = 2 * Math.PI * r;
  return (
    <div className="relative shrink-0" style={{ width: size, height: size }}>
      <svg width={size} height={size} className="-rotate-90">
        <circle cx={32} cy={32} r={r} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth={6} />
        <motion.circle cx={32} cy={32} r={r} fill="none" stroke="hsl(var(--primary))" strokeWidth={6} strokeLinecap="round" strokeDasharray={c} initial={{ strokeDashoffset: c }} animate={{ strokeDashoffset: c * (1 - Math.min(1, Math.max(0.03, pct))) }} transition={{ duration: reduce ? 0 : 1.1, ease: [0.22, 1, 0.36, 1] }} />
      </svg>
      <div className="absolute inset-0 grid place-items-center">{children}</div>
    </div>
  );
}

function CountUp({ value }: { value: number }) {
  const reduce = useReducedMotion();
  const [v, setV] = useState(reduce ? value : 0);
  React.useEffect(() => {
    if (reduce) {
      setV(value);
      return;
    }
    const c = animate(0, value, { duration: 1, ease: "easeOut", onUpdate: (x) => setV(x) });
    return () => c.stop();
  }, [value, reduce]);
  return <>{Math.round(v)}</>;
}

export default function CoachRoster({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [today] = useState(() => new Date().toISOString().slice(0, 10));
  const [fbFor, setFbFor] = useState<string | null>(null);
  const [msg, setMsg] = useState("");
  const [tone, setTone] = useState<"praise" | "adjust" | "question">("praise");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [sent, setSent] = useState<string[]>([]);

  const me = app?.me("coach");
  const loading = app ? app.loading("athlete") : false;
  const athletes = app ? app.rows("athlete") : [];
  const workouts = app ? app.rows("workout") : [];
  const checkins = app ? app.rows("checkin") : [];
  const feedback = app ? app.rows("feedback") : [];
  const coaches = app ? app.rows("coach") : [];
  const mine = coaches.find((c) => String(c.id) === me);

  const roster = useMemo(() => {
    return athletes.map((a) => {
      const id = String(a.id);
      const ws = workouts.filter((w) => String(w.athlete_id) === id);
      const days = new Set(ws.map((w) => ds(w.day)));
      const streak = calcStreak(days, today);
      const cks = checkins.filter((c) => String(c.athlete_id) === id).sort((x, y) => ds(y.day).localeCompare(ds(x.day)));
      const weekStart = addDays(today, -6);
      const week = ws.filter((w) => ds(w.day) >= weekStart).length;
      const last = [...ws].sort((x, y) => ds(y.day).localeCompare(ds(x.day)))[0];
      return { a, id, streak, last, ck: cks[0], week, target: num(a.weekly_target) || 4 };
    }).sort((x, y) => y.streak - x.streak);
  }, [athletes, workouts, checkins, today]);

  const flagged = roster.filter((r) => r.ck && (num(r.ck.soreness) >= 4 || num(r.ck.sleep_hours) < 6) && ds(r.ck.day) >= addDays(today, -2));
  const queue = useMemo(() => workouts.filter((w) => !feedback.some((f) => String(f.workout_id) === String(w.id)) && !sent.includes(String(w.id))).sort((a, b) => ds(b.day).localeCompare(ds(a.day))).slice(0, 8), [workouts, feedback, sent]);
  const avgStreak = roster.length ? roster.reduce((s, r) => s + r.streak, 0) / roster.length : 0;

  async function send(w: Row) {
    if (!app || !msg.trim()) return;
    setBusy(true);
    setErr("");
    try {
      await app.create("feedback", { workout_id: String(w.id), athlete_id: String(w.athlete_id), coach_id: me ?? null, coach_name: mine ? String(mine.name) : app.user.name, workout_title: String(w.title), message: msg.trim(), tone });
      setSent((s) => [...s, String(w.id)]);
      setFbFor(null);
      setMsg("");
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't send feedback.");
    }
    setBusy(false);
  }

  const first = (app?.user.name || "Coach").split(" ")[0];
  const fade = (i: number) => ({ initial: reduce ? false : { opacity: 0, y: 22 }, animate: { opacity: 1, y: 0 }, transition: { delay: reduce ? 0 : 0.06 * i, type: "spring" as const, stiffness: 120, damping: 18 } });

  return (
    <div className="min-h-screen bg-[#0a0b08] text-white antialiased">
      <header className="sticky top-0 z-30 flex items-center justify-between border-b border-white/[0.06] bg-[#0a0b08]/85 px-4 py-3 backdrop-blur-xl lg:px-10">
        <div className="flex items-center gap-2">
          <div className="grid h-9 w-9 place-items-center rounded-xl bg-primary text-black"><Zap size={20} strokeWidth={2.8} /></div>
          <span className="text-3xl font-extrabold uppercase tracking-tight" style={{ fontFamily: FONT }}>Stride</span>
          <span className="ml-2 rounded-full bg-white/[0.08] px-2 py-0.5 text-[10px] font-bold uppercase tracking-widest text-white/60">Coach</span>
        </div>
        <div className="flex items-center gap-3">
          <span className="hidden text-sm text-white/60 sm:block">{app?.user.name}</span>
          <button aria-label="Sign out" onClick={() => app?.auth.signOut()} className="grid h-9 w-9 place-items-center rounded-full bg-white/[0.06] text-white/60 hover:text-white"><LogOut size={16} /></button>
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-4 pb-16 pt-6 lg:px-10">
        <motion.div {...fade(0)}>
          <div className="text-xs font-semibold uppercase tracking-[0.2em] text-white/40">{new Date(today + "T00:00:00Z").toLocaleDateString(undefined, { weekday: "long", month: "short", day: "numeric", timeZone: "UTC" })}</div>
          <h1 className="text-4xl font-extrabold uppercase leading-[0.95] sm:text-5xl lg:text-6xl" style={{ fontFamily: FONT }}>Your <span className="text-primary">roster</span>, {first}</h1>
        </motion.div>

        <motion.div {...fade(1)} className="mt-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
          {[{ l: "Athletes", v: roster.length, I: Users }, { l: "Avg streak", v: avgStreak, I: Flame }, { l: "Awaiting feedback", v: queue.length, I: MessageSquare }, { l: "Flagged check-ins", v: flagged.length, I: AlertTriangle }].map((s) => (
            <div key={s.l} className={CARD + " p-4"}>
              <div className="flex items-center justify-between text-[11px] font-semibold uppercase tracking-[0.15em] text-white/45">{s.l}<s.I size={15} className="text-primary" /></div>
              <div className="mt-1 text-5xl font-extrabold leading-none" style={{ fontFamily: FONT }}><CountUp value={s.v} /></div>
            </div>
          ))}
        </motion.div>

        <div className="mt-6 grid gap-5 lg:grid-cols-12">
          <section className="lg:col-span-7">
            <h2 className="mb-3 text-2xl font-extrabold uppercase" style={{ fontFamily: FONT }}>Athletes</h2>
            {loading ? <div className="space-y-3">{[0, 1, 2].map((i) => <div key={i} className="h-24 animate-pulse rounded-3xl bg-white/5" />)}</div> : null}
            {!loading && roster.length === 0 ? <div className={CARD + " p-10 text-center"}><Users className="mx-auto text-primary" /><div className="mt-3 text-2xl font-extrabold uppercase" style={{ fontFamily: FONT }}>No athletes yet</div><p className="mt-1 text-sm text-white/50">Athletes assigned to you appear here.</p></div> : null}
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-1 xl:grid-cols-2">
              {roster.map((r, i) => {
                const stale = !r.ck || ds(r.ck.day) < addDays(today, -2);
                return (
                  <motion.button key={r.id} {...fade(2 + Math.min(i, 8) * 0.5)} whileHover={{ y: -4 }} whileTap={{ scale: 0.97 }} onClick={() => app?.navigate("/coach/athlete/" + r.id)} className={CARD + " flex items-center gap-4 p-4 text-left"}>
                    <MiniRing pct={r.week / r.target}>
                      <div className="h-11 w-11 overflow-hidden rounded-full bg-primary/20">{r.a.photo ? <img alt="" src={String(r.a.photo)} className="h-full w-full object-cover" /> : null}</div>
                    </MiniRing>
                    <div className="min-w-0 flex-1">
                      <div className="truncate text-lg font-bold">{String(r.a.name)}</div>
                      <div className="flex items-center gap-2 text-xs text-white/50">
                        <span className={"flex items-center gap-1 font-bold " + (r.streak ? "text-primary" : "text-white/40")}><Flame size={13} />{r.streak}d</span>
                        <span>·</span>
                        <span>{r.week}/{r.target} this week</span>
                      </div>
                      <div className="mt-1 flex items-center gap-1.5 text-[11px] text-white/45">
                        {r.ck ? <><span>{MOODS[Math.max(0, Math.min(4, num(r.ck.mood) - 1))]}</span><span>{num(r.ck.sleep_hours)}h</span><span className={num(r.ck.soreness) >= 4 ? "font-bold text-orange-400" : ""}>sore {num(r.ck.soreness)}/5</span><span>· {ago(ds(r.ck.day), today)}</span></> : <span>No check-ins yet</span>}
                        {stale ? <span className="ml-auto rounded-full bg-amber-400/15 px-1.5 text-[9px] font-bold uppercase text-amber-300">quiet</span> : null}
                      </div>
                    </div>
                    <ChevronRight size={18} className="text-white/30" />
                  </motion.button>
                );
              })}
            </div>
          </section>

          <section className="lg:col-span-5">
            <h2 className="mb-3 text-2xl font-extrabold uppercase" style={{ fontFamily: FONT }}>Review queue</h2>
            {queue.length === 0 ? <div className={CARD + " p-8 text-center"}><div className="mx-auto grid h-12 w-12 place-items-center rounded-full bg-primary text-black"><Check strokeWidth={3} /></div><div className="mt-3 text-xl font-extrabold uppercase" style={{ fontFamily: FONT }}>All caught up</div><p className="text-sm text-white/50">Every logged workout has your feedback.</p></div> : null}
            <div className="space-y-3">
              <AnimatePresence initial={false}>
                {queue.map((w, i) => {
                  const id = String(w.id);
                  const ath = athletes.find((a) => String(a.id) === String(w.athlete_id));
                  const open = fbFor === id;
                  return (
                    <motion.div key={id} layout initial={reduce ? false : { opacity: 0, y: 18 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, x: 60, height: 0 }} transition={{ delay: Math.min(i, 6) * 0.04 }} className={CARD + " overflow-hidden"}>
                      <button onClick={() => { setFbFor(open ? null : id); setErr(""); }} className="flex w-full items-center gap-3 p-4 text-left">
                        <div className="h-10 w-10 shrink-0 overflow-hidden rounded-full bg-primary/20">{ath?.photo ? <img alt="" src={String(ath.photo)} className="h-full w-full object-cover" /> : null}</div>
                        <div className="min-w-0 flex-1"><div className="truncate font-bold">{String(w.athlete_name ?? ath?.name ?? "Athlete")} · {String(w.title)}</div><div className="text-xs text-white/45">{ago(ds(w.day), today)} · effort {num(w.effort)}/10 · {num(w.duration_min)} min</div></div>
                        <span className="rounded-full bg-primary px-2.5 py-1 text-[10px] font-extrabold uppercase text-black">Reply</span>
                      </button>
                      <AnimatePresence initial={false}>
                        {open ? (
                          <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                            <div className="space-y-3 border-t border-white/[0.06] p-4">
                              {w.notes ? <p className="text-sm italic text-white/60">“{String(w.notes)}”</p> : null}
                              <div className="flex gap-2">
                                {(["praise", "adjust", "question"] as const).map((t) => <button key={t} onClick={() => setTone(t)} className={"rounded-full px-3 py-1 text-xs font-semibold capitalize " + (tone === t ? "bg-primary text-black" : "bg-white/[0.07] text-white/65")}>{t}</button>)}
                              </div>
                              <textarea rows={3} value={msg} onChange={(e) => setMsg(e.target.value)} placeholder="Feedback the athlete will see…" className="w-full rounded-2xl border border-white/10 bg-white/[0.04] p-3 text-sm text-white outline-none focus:border-primary" />
                              {err ? <p className="text-sm text-red-300">{err}</p> : null}
                              <motion.button whileTap={{ scale: 0.96 }} disabled={busy || !msg.trim()} onClick={() => void send(w)} className="flex h-11 w-full items-center justify-center gap-2 rounded-2xl bg-primary font-extrabold uppercase text-black disabled:opacity-50" style={{ fontFamily: FONT }}><Send size={16} />{busy ? "Sending…" : "Send feedback"}</motion.button>
                            </div>
                          </motion.div>
                        ) : null}
                      </AnimatePresence>
                    </motion.div>
                  );
                })}
              </AnimatePresence>
            </div>
            <div className={CARD + " mt-5 flex items-center gap-3 p-4 text-sm text-white/55"}><Clipboard size={18} className="text-primary" /> Open an athlete to assign their weekly plan.</div>
          </section>
        </div>
      </main>
    </div>
  );
}

import React, { useMemo, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { LogOut, Zap, Flame, ArrowLeft, Send, Check, Calendar, MessageSquare, Sparkles } from "lucide-react";

type Row = Record<string, unknown>;
const FONT = "'Barlow Condensed','Oswald','Arial Narrow',Impact,sans-serif";
const CARD = "rounded-3xl border border-white/[0.07] bg-[#13150e] shadow-[0_1px_0_rgba(255,255,255,0.05)_inset,0_24px_48px_-24px_rgba(0,0,0,0.9)]";
const INPUT = "h-11 w-full rounded-xl border border-white/10 bg-white/[0.04] px-3 text-sm text-white outline-none transition focus:border-primary";
const ds = (v: unknown): string => String(v ?? "").slice(0, 10);
const num = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
const addDays = (s: string, n: number): string => {
  const d = new Date(s + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};
const dow = (s: string): number => (new Date(s + "T00:00:00Z").getUTCDay() + 6) % 7;
const fmt = (s: string): string => new Date(s + "T00:00:00Z").toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric", timeZone: "UTC" });
const MOODS = ["😞", "😕", "😐", "🙂", "🔥"];
const KINDS = ["strength", "run", "conditioning", "mobility", "ride", "rest"];
const TEMPLATE = [
  { title: "Lower Body Strength", kind: "strength", details: "Squat 5x5 · RDL 3x8 · Lunges 3x10", min: "60" },
  { title: "Easy Run", kind: "run", details: "6 km easy pace", min: "40" },
  { title: "Upper Body Strength", kind: "strength", details: "Bench 5x5 · Rows 4x8 · OHP 3x8", min: "60" },
  { title: "Mobility Flow", kind: "mobility", details: "Hips, thoracic, ankles", min: "30" },
  { title: "Tempo Intervals", kind: "run", details: "4 x 1 km at tempo", min: "45" },
  { title: "Long Session", kind: "conditioning", details: "Steady aerobic work", min: "75" },
  { title: "Rest Day", kind: "rest", details: "Walk, sleep, eat well", min: "0" },
];
function calcStreak(days: Set<string>, today: string): number {
  let cur = days.has(today) ? today : addDays(today, -1);
  let n = 0;
  while (days.has(cur)) {
    n++;
    cur = addDays(cur, -1);
  }
  return n;
}

export default function CoachAthlete({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [today] = useState(() => new Date().toISOString().slice(0, 10));
  const id = app?.params.id || "";
  const me = app?.me("coach");
  const athletes = app ? app.rows("athlete") : [];
  const a = athletes.find((x) => String(x.id) === id);
  const coaches = app ? app.rows("coach") : [];
  const mine = coaches.find((c) => String(c.id) === me);
  const workouts = useMemo(() => (app ? app.rows("workout") : []).filter((w) => String(w.athlete_id) === id).sort((x, y) => ds(y.day).localeCompare(ds(x.day))), [app, id]);
  const checkins = (app ? app.rows("checkin") : []).filter((c) => String(c.athlete_id) === id).sort((x, y) => ds(y.day).localeCompare(ds(x.day)));
  const feedback = (app ? app.rows("feedback") : []).filter((f) => String(f.athlete_id) === id);
  const plans = (app ? app.rows("plan_day") : []).filter((p) => String(p.athlete_id) === id);
  const allPlans = app ? app.rows("plan_day") : [];

  const [tab, setTab] = useState<"logs" | "plan" | "checkins">("logs");
  const [fbFor, setFbFor] = useState<string | null>(null);
  const [msg, setMsg] = useState("");
  const [tone, setTone] = useState<"praise" | "adjust" | "question">("praise");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const nextMon = addDays(today, 7 - dow(today));
  const [weekStart, setWeekStart] = useState(nextMon);
  const [draft, setDraft] = useState(TEMPLATE);
  const [planBusy, setPlanBusy] = useState(false);
  const [planMsg, setPlanMsg] = useState("");

  const days = useMemo(() => new Set(workouts.map((w) => ds(w.day))), [workouts]);
  const streak = calcStreak(days, today);
  const wk = workouts.filter((w) => ds(w.day) >= addDays(today, -6));
  const mins = wk.reduce((s, w) => s + num(w.duration_min), 0);
  const vol = wk.reduce((s, w) => s + num(w.volume), 0);
  const eff = wk.length ? wk.reduce((s, w) => s + num(w.effort), 0) / wk.length : 0;
  const series = Array.from({ length: 14 }, (_, i) => {
    const d = addDays(today, i - 13);
    return { d, v: workouts.filter((w) => ds(w.day) === d).reduce((s, w) => s + num(w.duration_min), 0) };
  });
  const maxV = Math.max(1, ...series.map((s) => s.v));
  const weekPlans = plans.filter((p) => ds(p.day) >= weekStart && ds(p.day) <= addDays(weekStart, 6)).sort((x, y) => ds(x.day).localeCompare(ds(y.day)));

  async function sendFb(w: Row) {
    if (!app || !msg.trim()) return;
    setBusy(true);
    setErr("");
    try {
      await app.create("feedback", { workout_id: String(w.id), athlete_id: id, coach_id: me ?? null, coach_name: mine ? String(mine.name) : app.user.name, workout_title: String(w.title), message: msg.trim(), tone });
      setFbFor(null);
      setMsg("");
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't send feedback.");
    }
    setBusy(false);
  }

  const [aiBusy, setAiBusy] = useState(false);
  const [aiNote, setAiNote] = useState("");
  const [aiFallback, setAiFallback] = useState(false);
  const [aiSent, setAiSent] = useState(false);
  const [aiErr, setAiErr] = useState("");
  const latest = workouts[0];

  async function draftNote() {
    if (!app || !a) return;
    setAiBusy(true);
    setAiFallback(false);
    setAiSent(false);
    setAiErr("");
    const wl = workouts.slice(0, 7).map((w) => ds(w.day) + ": " + String(w.title) + " (" + String(w.kind) + "), effort " + num(w.effort) + "/10, " + num(w.duration_min) + " min" + (w.notes ? ", note: " + String(w.notes).slice(0, 80) : ""));
    const cl = checkins.slice(0, 7).map((c) => ds(c.day) + ": sleep " + num(c.sleep_hours) + " h, mood " + num(c.mood) + "/5, soreness " + num(c.soreness) + "/5" + (c.note ? ", " + String(c.note).slice(0, 80) : ""));
    try {
      const r = await app.ai.ask("Athlete: " + String(a.name) + ". Goal: " + String(a.goal ?? "get fitter") + ".\nLast workouts:\n" + (wl.join("\n") || "none") + "\nCheck-ins:\n" + (cl.join("\n") || "none") + "\nWrite the feedback note.", { system: "You are a warm, encouraging strength and endurance coach writing a short note to your athlete. 3 to 4 sentences, first person, address them by first name, cite one concrete detail from the logs, end with one clear next step. No lists, no emoji.", maxTokens: 220 });
      const t = r.trim();
      if (!t) throw new Error("empty");
      setAiNote(t);
    } catch (e) {
      setAiFallback(true);
      setAiNote("");
    }
    setAiBusy(false);
  }

  async function sendAiNote() {
    if (!app || !latest || !aiNote.trim()) return;
    setAiBusy(true);
    setAiErr("");
    try {
      await app.create("feedback", { workout_id: String(latest.id), athlete_id: id, coach_id: me ?? null, coach_name: mine ? String(mine.name) : app.user.name, workout_title: String(latest.title), message: aiNote.trim(), tone: "praise" });
      setAiSent(true);
      setAiNote("");
    } catch (e) {
      setAiErr(e instanceof Error ? e.message : "Couldn't send the note.");
    }
    setAiBusy(false);
  }

  async function assign() {
    if (!app) return;
    setPlanBusy(true);
    setPlanMsg("");
    try {
      let n = 0;
      for (let i = 0; i < draft.length; i++) {
        const r = draft[i];
        if (!r.title.trim()) continue;
        const img = allPlans.find((p) => String(p.kind) === r.kind && p.image)?.image;
        await app.create("plan_day", { athlete_id: id, coach_id: me ?? null, day: addDays(weekStart, i), title: r.title.trim(), kind: r.kind, details: r.details, duration_min: num(r.min), ...(img ? { image: String(img) } : {}) });
        n++;
      }
      setPlanMsg("Assigned " + n + " days to " + String(a?.name ?? "athlete") + " — week of " + fmt(weekStart));
    } catch (e) {
      setPlanMsg(e instanceof Error ? e.message : "Couldn't assign the plan.");
    }
    setPlanBusy(false);
  }

  const fade = (i: number) => ({ initial: reduce ? false : { opacity: 0, y: 20 }, animate: { opacity: 1, y: 0 }, transition: { delay: reduce ? 0 : 0.06 * i } });
  const tabs: [typeof tab, string][] = [["logs", "Logs"], ["plan", "Weekly plan"], ["checkins", "Check-ins"]];

  return (
    <div className="min-h-screen bg-[#0a0b08] text-white antialiased">
      <header className="sticky top-0 z-30 flex items-center justify-between border-b border-white/[0.06] bg-[#0a0b08]/85 px-4 py-3 backdrop-blur-xl lg:px-10">
        <motion.button whileTap={{ scale: 0.92 }} onClick={() => app?.navigate("/coach")} className="flex items-center gap-2 text-sm font-semibold text-white/70"><ArrowLeft size={18} /> Roster</motion.button>
        <div className="flex items-center gap-2"><div className="grid h-8 w-8 place-items-center rounded-lg bg-primary text-black"><Zap size={18} strokeWidth={2.8} /></div><span className="text-2xl font-extrabold uppercase" style={{ fontFamily: FONT }}>Stride</span></div>
        <button aria-label="Sign out" onClick={() => app?.auth.signOut()} className="grid h-9 w-9 place-items-center rounded-full bg-white/[0.06] text-white/60"><LogOut size={16} /></button>
      </header>

      <main className="mx-auto max-w-7xl px-4 pb-16 pt-6 lg:px-10">
        {!a ? <div className={CARD + " h-40 animate-pulse"} /> : (
          <div className="grid gap-5 lg:grid-cols-12">
            <motion.aside {...fade(0)} className="space-y-4 lg:col-span-4">
              <div className={CARD + " relative overflow-hidden p-6"}>
                {a.photo ? <img alt="" src={String(a.photo)} className="absolute inset-0 h-full w-full object-cover opacity-30" /> : null}
                <div className="absolute inset-0 bg-gradient-to-t from-[#13150e] via-[#13150e]/80 to-transparent" />
                <div className="relative pt-24">
                  <div className="text-xs font-bold uppercase tracking-[0.2em] text-primary">{String(a.level ?? "athlete")}</div>
                  <h1 className="text-5xl font-extrabold uppercase leading-[0.95]" style={{ fontFamily: FONT }}>{String(a.name)}</h1>
                  <p className="mt-2 text-sm text-white/65">Goal: {String(a.goal ?? "—")}</p>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                {[{ l: "Streak", v: streak + "d", I: true }, { l: "Sessions 7d", v: String(wk.length) }, { l: "Minutes 7d", v: String(mins) }, { l: "Avg effort", v: eff.toFixed(1) }].map((s) => (
                  <div key={s.l} className={CARD + " p-4"}><div className="flex items-center gap-1 text-[11px] font-semibold uppercase tracking-[0.15em] text-white/45">{s.I ? <Flame size={13} className="text-primary" /> : null}{s.l}</div><div className="text-4xl font-extrabold" style={{ fontFamily: FONT }}>{s.v}</div></div>
                ))}
              </div>
              <div className={CARD + " p-5"}>
                <div className="mb-3 text-xs font-semibold uppercase tracking-[0.2em] text-white/45">Minutes · last 14 days · {vol.toLocaleString()} kg this week</div>
                <div className="flex h-28 items-end gap-1">
                  {series.map((s, i) => <motion.div key={s.d} initial={reduce ? false : { height: 0 }} animate={{ height: Math.max(3, (s.v / maxV) * 100) + "%" }} transition={{ delay: i * 0.03, type: "spring", stiffness: 120, damping: 14 }} className={"flex-1 rounded-t-md " + (s.v ? "bg-primary" : "bg-white/[0.07]")} />)}
                </div>
              </div>
            </motion.aside>

            <section className="lg:col-span-8">
              <div className="flex w-fit rounded-full bg-white/[0.06] p-1">
                {tabs.map(([k, l]) => (
                  <button key={k} onClick={() => setTab(k)} className="relative rounded-full px-4 py-2 text-sm font-semibold">
                    {tab === k && <motion.span layoutId="coach-tab" className="absolute inset-0 rounded-full bg-primary" />}
                    <span className={tab === k ? "relative text-black" : "relative text-white/65"}>{l}</span>
                  </button>
                ))}
              </div>

              <div className="mt-4 space-y-3">
                {tab === "logs" ? (
                  <motion.div initial={reduce ? false : { opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} className={CARD + " relative overflow-hidden p-5"}>
                    <div className="pointer-events-none absolute -right-10 -top-10 h-40 w-40 rounded-full bg-primary/15 blur-3xl" />
                    <div className="relative flex flex-wrap items-center justify-between gap-3">
                      <div>
                        <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.2em] text-primary"><Sparkles size={15} /> Coach notes</div>
                        <div className="mt-1 text-sm text-white/55">A draft from {a ? String(a.name).split(" ")[0] : "the athlete"}'s last 7 workouts and check-ins. Edit it, then send.</div>
                      </div>
                      <motion.button whileTap={{ scale: 0.95 }} onClick={() => void draftNote()} disabled={aiBusy || workouts.length === 0} className="flex h-11 items-center gap-2 rounded-2xl bg-primary px-5 font-extrabold uppercase text-black disabled:opacity-50" style={{ fontFamily: FONT }}><Sparkles size={16} className={aiBusy && !aiNote ? "animate-pulse" : ""} />{aiBusy && !aiNote ? "Drafting…" : aiNote ? "Redraft" : "Draft feedback"}</motion.button>
                    </div>
                    <AnimatePresence initial={false}>
                      {aiFallback ? <motion.p key="fb" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="relative mt-3 rounded-2xl border border-white/10 bg-white/[0.04] px-4 py-3 text-sm text-white/70">AI is resting right now, try again soon.</motion.p> : null}
                      {aiNote ? (
                        <motion.div key="note" initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }} className="relative overflow-hidden">
                          <textarea aria-label="Draft feedback note" rows={5} value={aiNote} onChange={(e) => setAiNote(e.target.value)} className="mt-3 w-full rounded-2xl border border-primary/30 bg-primary/[0.06] p-4 text-sm leading-relaxed text-white outline-none focus:border-primary" />
                          <div className="mt-2 flex flex-wrap items-center justify-between gap-2">
                            <span className="text-xs text-white/45">Sends on {latest ? String(latest.title) : "the latest workout"}</span>
                            <motion.button whileTap={{ scale: 0.95 }} onClick={() => void sendAiNote()} disabled={aiBusy || !aiNote.trim() || !latest} className="flex h-10 items-center gap-2 rounded-2xl bg-white px-5 text-sm font-extrabold uppercase text-black disabled:opacity-50" style={{ fontFamily: FONT }}><Send size={14} />Send note</motion.button>
                          </div>
                        </motion.div>
                      ) : null}
                      {aiSent ? <motion.p key="sent" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="relative mt-3 flex items-center gap-2 text-sm text-primary"><Check size={16} />Note sent.</motion.p> : null}
                      {aiErr ? <motion.p key="err" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="relative mt-3 text-sm text-red-300">{aiErr}</motion.p> : null}
                    </AnimatePresence>
                  </motion.div>
                ) : null}
                {tab === "logs" && workouts.length === 0 ? <div className={CARD + " p-10 text-center text-white/50"}>No workouts logged yet.</div> : null}
                {tab === "logs" && workouts.slice(0, 12).map((w, i) => {
                  const wid = String(w.id);
                  const fbs = feedback.filter((f) => String(f.workout_id) === wid);
                  const open = fbFor === wid;
                  return (
                    <motion.div key={wid} layout initial={reduce ? false : { opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: Math.min(i, 8) * 0.04 }} className={CARD + " p-4"}>
                      <div className="flex items-center gap-3">
                        <div className="grid h-12 w-12 shrink-0 place-items-center rounded-2xl bg-primary/15 text-2xl font-extrabold text-primary" style={{ fontFamily: FONT }}>{num(w.effort)}</div>
                        <div className="min-w-0 flex-1"><div className="truncate font-bold">{String(w.title)}</div><div className="text-xs text-white/45">{fmt(ds(w.day))} · {num(w.duration_min)} min{num(w.volume) ? " · " + num(w.volume).toLocaleString() + " kg" : ""}{num(w.distance_km) ? " · " + num(w.distance_km) + " km" : ""}</div></div>
                        <motion.button whileTap={{ scale: 0.93 }} onClick={() => { setFbFor(open ? null : wid); setErr(""); }} className="flex items-center gap-1 rounded-full bg-white/[0.08] px-3 py-1.5 text-xs font-semibold"><MessageSquare size={13} />{fbs.length ? fbs.length : "Reply"}</motion.button>
                      </div>
                      {w.notes ? <p className="mt-2 text-sm italic text-white/55">“{String(w.notes)}”</p> : null}
                      {fbs.map((f) => <div key={String(f.id)} className="mt-2 rounded-2xl border border-primary/25 bg-primary/10 p-3 text-sm"><span className="mr-2 text-[10px] font-bold uppercase tracking-widest text-primary">{String(f.tone)}</span>{String(f.message)}</div>)}
                      <AnimatePresence initial={false}>
                        {open ? (
                          <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                            <div className="space-y-3 pt-3">
                              <div className="flex gap-2">{(["praise", "adjust", "question"] as const).map((t) => <button key={t} onClick={() => setTone(t)} className={"rounded-full px-3 py-1 text-xs font-semibold capitalize " + (tone === t ? "bg-primary text-black" : "bg-white/[0.07] text-white/65")}>{t}</button>)}</div>
                              <textarea rows={3} value={msg} onChange={(e) => setMsg(e.target.value)} placeholder="Feedback the athlete will see…" className="w-full rounded-2xl border border-white/10 bg-white/[0.04] p-3 text-sm text-white outline-none focus:border-primary" />
                              {err ? <p className="text-sm text-red-300">{err}</p> : null}
                              <motion.button whileTap={{ scale: 0.96 }} disabled={busy || !msg.trim()} onClick={() => void sendFb(w)} className="flex h-11 w-full items-center justify-center gap-2 rounded-2xl bg-primary font-extrabold uppercase text-black disabled:opacity-50" style={{ fontFamily: FONT }}><Send size={16} />{busy ? "Sending…" : "Send feedback"}</motion.button>
                            </div>
                          </motion.div>
                        ) : null}
                      </AnimatePresence>
                    </motion.div>
                  );
                })}

                {tab === "plan" ? (
                  <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-3">
                    <div className={CARD + " p-4"}>
                      <div className="flex flex-wrap items-end gap-3">
                        <label className="text-[11px] font-semibold uppercase tracking-widest text-white/45"><span className="mb-1 flex items-center gap-1"><Calendar size={12} /> Week starting (Monday)</span><input type="date" className={INPUT} value={weekStart} onChange={(e) => setWeekStart(e.target.value)} /></label>
                        <span className="pb-3 text-xs text-white/45">{weekPlans.length ? weekPlans.length + " days already planned this week" : "Nothing planned for this week yet"}</span>
                      </div>
                    </div>
                    {draft.map((r, i) => (
                      <motion.div key={i} initial={reduce ? false : { opacity: 0, x: -16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.04 }} className={CARD + " p-3"}>
                        <div className="mb-2 text-[11px] font-bold uppercase tracking-widest text-primary">{fmt(addDays(weekStart, i))}</div>
                        <div className="grid gap-2 sm:grid-cols-12">
                          <input className={INPUT + " sm:col-span-5"} value={r.title} placeholder="Session title" onChange={(e) => setDraft((d) => d.map((x, k) => (k === i ? { ...x, title: e.target.value } : x)))} />
                          <select className={INPUT + " sm:col-span-3"} value={r.kind} onChange={(e) => setDraft((d) => d.map((x, k) => (k === i ? { ...x, kind: e.target.value } : x)))}>{KINDS.map((k) => <option key={k} value={k}>{k}</option>)}</select>
                          <input className={INPUT + " sm:col-span-2"} type="number" value={r.min} placeholder="Min" onChange={(e) => setDraft((d) => d.map((x, k) => (k === i ? { ...x, min: e.target.value } : x)))} />
                          <input className={INPUT + " sm:col-span-12"} value={r.details} placeholder="Details (sets, reps, pace)" onChange={(e) => setDraft((d) => d.map((x, k) => (k === i ? { ...x, details: e.target.value } : x)))} />
                        </div>
                      </motion.div>
                    ))}
                    <AnimatePresence>{planMsg ? <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="flex items-center gap-2 rounded-2xl border border-primary/30 bg-primary/10 px-4 py-3 text-sm text-primary"><Check size={16} />{planMsg}</motion.p> : null}</AnimatePresence>
                    <motion.button whileTap={{ scale: 0.97 }} disabled={planBusy} onClick={() => void assign()} className="flex h-14 w-full items-center justify-center gap-2 rounded-2xl bg-primary text-xl font-extrabold uppercase text-black shadow-[0_14px_40px_-8px_rgba(198,244,50,0.55)] disabled:opacity-60" style={{ fontFamily: FONT }}>{planBusy ? "Assigning…" : "Assign weekly plan"}</motion.button>
                    {weekPlans.length ? <div className={CARD + " p-4"}><div className="mb-2 text-xs font-semibold uppercase tracking-[0.2em] text-white/45">Already on the calendar</div>{weekPlans.map((p) => <div key={String(p.id)} className="flex justify-between border-b border-white/[0.05] py-2 text-sm last:border-0"><span className="text-white/50">{fmt(ds(p.day))}</span><span className="font-semibold">{String(p.title)}</span></div>)}</div> : null}
                  </motion.div>
                ) : null}

                {tab === "checkins" && checkins.length === 0 ? <div className={CARD + " p-10 text-center text-white/50"}>No check-ins yet.</div> : null}
                {tab === "checkins" && checkins.map((c, i) => (
                  <motion.div key={String(c.id)} initial={reduce ? false : { opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: Math.min(i, 8) * 0.04 }} className={CARD + " flex items-center gap-4 p-4"}>
                    <div className="text-3xl">{MOODS[Math.max(0, Math.min(4, num(c.mood) - 1))]}</div>
                    <div className="min-w-0 flex-1"><div className="text-sm font-bold">{fmt(ds(c.day))}</div><div className="text-xs text-white/50">{num(c.sleep_hours)} h sleep · soreness {num(c.soreness)}/5</div>{c.note ? <div className="mt-1 text-sm italic text-white/60">“{String(c.note)}”</div> : null}</div>
                    {num(c.soreness) >= 4 || num(c.sleep_hours) < 6 ? <span className="rounded-full bg-orange-500/15 px-2 py-1 text-[10px] font-bold uppercase text-orange-300">Watch</span> : null}
                  </motion.div>
                ))}
              </div>
            </section>
          </div>
        )}
      </main>
    </div>
  );
}
